package cc.ataglace.molebutter.marketplaceelevenst.internal;
import java.util.*;
import org.springframework.stereotype.Component;
import tools.jackson.databind.ObjectMapper;
import cc.ataglace.molebutter.marketplace.api.*;
import cc.ataglace.molebutter.marketplace.api.MarketplaceDrafts.*;
import cc.ataglace.molebutter.marketplace.api.MarketplaceWriteGateway.*;
import cc.ataglace.molebutter.media.api.*;
import static cc.ataglace.molebutter.marketplace.api.PartnerFormSupport.*;
@Component
final class ElevenstDocuments implements StandaloneProductDocuments {
 private final ElevenstCatalog catalog;private final ObjectMapper json;private final ImageInspection inspection;
 ElevenstDocuments(ElevenstCatalog catalog,ObjectMapper json,ImageInspection inspection){this.catalog=catalog;this.json=json;this.inspection=inspection;}
 public String market(){return "ELEVENST";}public String accountKey(){return catalog.client.account();}
 public boolean supports(Document d){return d.markets()!=null&&d.markets().containsKey(Market.ELEVENST);}
 public Document normalize(Document d){var i=input(d);return i==null?d:withInput(d,market(),ElevenstRules.normalize(i));}
 PartnerEditor.Input input(Document d){return PartnerFormSupport.input(d,market());}
 public Document newDocument(Document reference){
  reference=MarketplaceDocuments.normalize(reference);var previous=input(reference);var state=reference.markets().get(Market.ELEVENST).elevenst();if(previous!=null&&state.editorState()==null)return normalize(reference);
  var input=fromCommon(reference,ElevenstRules.KEYS,ElevenstRules.DEFAULTS);var fields=new LinkedHashMap<>(input.fields());var m=reference.markets().get(Market.ELEVENST);fields.put("dispCtgrNo",m==null?"":m.categoryCode());
  long lowest=reference.options().stream().filter(o->o.price()!=null&&o.price().matches("[0-9]+")).mapToLong(o->Long.parseLong(o.price())).min().orElse(0);long base=reference.options().stream().filter(o->o.originalPrice()!=null&&o.originalPrice().matches("[0-9]+")).mapToLong(o->Long.parseLong(o.originalPrice())).max().orElse(lowest);base=Math.max(base,lowest);
  fields.put("selPrc",Long.toString(base));fields.put("cuponcheck",base>lowest?"Y":"N");fields.put("dscAmtPercnt",Long.toString(base-lowest));fields.put("cupnDscMthdCd","01");
  fields.putAll(MarketplaceCommonSettings.partnerFields("ELEVENST",reference));var delivery=reference.delivery();if(delivery!=null){fields.put("rtngdDlvCst",delivery.returnCharge());fields.put("asDetail",MarketplaceCommonSettings.service(reference.common()));if(delivery.chargeType().equals("FREE"))fields.put("dlvCstInstBasiCd","01");else if(delivery.chargeType().equals("NOT_FREE")){fields.put("dlvCstInstBasiCd","02");fields.put("dlvCst1",delivery.charge());}else if(delivery.chargeType().equals("CONDITIONAL_FREE")){fields.put("dlvCstInstBasiCd","03");fields.put("dlvCst1",delivery.charge());fields.put("PrdFrDlvBasiAmt",delivery.freeOver());}}
  if(m!=null&&m.addressBook()!=null){if(m.addressBook().outbound()!=null)fields.put("addrSeqOut",m.addressBook().outbound().code());if(m.addressBook().returns()!=null)fields.put("addrSeqIn",m.addressBook().returns().code());}
  return ElevenstInheritance.merge(withInput(reference,market(),new PartnerEditor.Input(Map.copyOf(fields),input.options(),input.images(),input.description(),input.noticeType(),input.notices(),input.certifications())),previous,state==null?ElevenstInheritance.EMPTY:state.editorState());
 }
 public Observed standalone(Long actor,String product){accessSnapshot(actor);var snapshot=catalog.snapshot(product);var o=snapshot.observation();var d=PartnerFormSupport.document(market(),o.input(),List.of(Market.ELEVENST),ElevenstRules.KEYS);d=restricted(d,snapshot);return new Observed(d,new Mapping(accountKey(),product,o.identities().stream().map(i->new OptionMapping(i.optionId(),i.remoteId(),null)).toList()));}
 public Document observe(Long actor,Document reference,Mapping mapping){if(!accountKey().equals(mapping.accountKey()))throw invalid("11번가 계정이 변경되었습니다.");accessSnapshot(actor);var snapshot=catalog.snapshot(mapping.sellerProductId());var o=snapshot.observation();var ids=new HashMap<String,String>();for(var identity:o.identities()){var match=mapping.options().stream().filter(m->identity.remoteId().equals(m.sellerProductItemId())).findFirst().orElseThrow(()->invalid("11번가 옵션 구성이 변경되었습니다. 다시 연결해 주세요."));ids.put(identity.optionId(),match.optionId());}if(ids.size()!=mapping.options().size())throw invalid("11번가 옵션 구성이 변경되었습니다.");var input=o.input();var rows=input.options().stream().map(i->new PartnerEditor.Option(ids.get(i.id()),i.name(),i.sku(),i.price(),i.quantity(),i.attributes(),i.usable())).toList();return restricted(withInput(reference,market(),new PartnerEditor.Input(input.fields(),rows,input.images(),input.description(),input.noticeType(),input.notices(),input.certifications())),snapshot);}
 private void accessSnapshot(Long actor){catalog.schema(actor);}
 private Document restricted(Document d,ElevenstCatalog.Snapshot snapshot){var unknown=new ArrayList<String>();if(!snapshot.supported())unknown.add("READ_ONLY_PRODUCT");if(!snapshot.values().containsKey("prdImage01")||java.util.stream.IntStream.rangeClosed(1,4).anyMatch(n->{String url=snapshot.values().getOrDefault("prdImage0"+n,"");return !url.isBlank()&&!url.startsWith("https://");}))unknown.add("UNVERIFIED_IMAGES");return ElevenstInheritance.state(d,unknown.isEmpty()?null:new EditorState(1,List.of(),"CUSTOM","CUSTOM",null,null,null,null,List.copyOf(unknown)));}
 public String readOnlyReason(Document d){var config=d.markets().get(Market.ELEVENST);return config!=null&&config.elevenst()!=null&&config.elevenst().editorState()!=null&&config.elevenst().editorState().unmapped().contains("READ_ONLY_PRODUCT")?"해외·예약·중고·특수 옵션 또는 유형 미확인 상품은 조회만 지원합니다.":null;}
 public boolean supportsPendingEdits(){return true;}
 public MarketplaceEditing.PendingRebase rebase(Document before,Document current,List<MarketplaceEditing.Change> changes){return PartnerFormSupport.rebase(input(before),input(current),changes,json);}
 public Document apply(Document d,List<MarketplaceEditing.Change> changes){return ElevenstInheritance.mark(d,withInput(d,market(),ElevenstRules.normalize(PartnerFormSupport.apply(input(d),changes,json))),json);}
 public List<MarketplaceEditing.Change> observedComparisonFields(Document d){var config=d.markets().get(Market.ELEVENST).elevenst();boolean images=config.editorState()==null||!config.editorState().unmapped().contains("UNVERIFIED_IMAGES");return comparisonFields(d).stream().filter(c->images||!c.path().equals("partner.images")).filter(c->!Set.of("partner.options.attributes","partner.options.usable").contains(c.path())).filter(c->c.optionId()==null||!Set.of("partner.options.price","partner.options.quantity").contains(c.path())||c.value()!=null&&!c.value().toString().isBlank()).toList();}
 public List<MarketplaceEditing.Change> comparisonFields(Document d){return PartnerFormSupport.comparisonFields(input(d),json);}
 public List<MarketplaceEditing.Change> normalizeChanges(Document d,List<MarketplaceEditing.Change> changes){return PartnerFormSupport.granular(input(d),changes,json);}
 public Document saveTarget(Document reference,Document desired){return ElevenstInheritance.state(withInput(reference,market(),input(desired)),desired.markets().get(Market.ELEVENST).elevenst().editorState());}
 public Document commonReference(Document d){var i=input(d);var common=PartnerFormSupport.document(market(),i,d.selectedMarkets(),ElevenstRules.KEYS);return new Document(d.id(),d.revision(),common.common(),common.options().stream().map(o->{String normal="";try{normal=Long.toString(Long.parseLong(ElevenstRules.field(i,"selPrc"))+Long.parseLong(o.price())-ElevenstRules.discounted(i));}catch(RuntimeException ignored){}return new Option(o.id(),o.name(),o.sku(),o.price(),o.quantity(),o.attributes(),normal);}).toList(),common.stockMode(),common.productQuantity(),common.services(),common.media(),d.delivery(),d.selectedMarkets(),d.markets());}
 public void validateSettings(Long actor,Document d,boolean create,List<MarketplaceEditing.Change> changes){if(!create&&changes.stream().anyMatch(c->c.path().matches("partner\\.fields\\.(aplBgnDy|aplEndDy|selPrdClfCd|selTermUseYn)")))ElevenstRules.validatePeriod(input(d));}
 public void validate(Long actor,Document d,boolean create){if(create)MarketplaceCommonSettings.validate(d);if(!create&&readOnlyReason(d)!=null)throw invalid(readOnlyReason(d));ElevenstRules.validate(input(d),create);}
 public List<ImageInspection.Input> images(Document d,Set<String> existing){var input=input(d);var images=new ArrayList<ImageInspection.Input>();for(var i:input.images())images.add(new ImageInspection.Input(market(),i.representative()?"REPRESENTATION":"DETAIL",null,i.id(),i.url(),i.assetId(),existing.contains(i.url())));images.addAll(ImageInspection.descriptionInputs(market(),input.description(),"description").stream().map(i->new ImageInspection.Input(i.market(),i.role(),i.optionId(),i.imageId(),i.url(),i.assetId(),existing.contains(i.url()))).toList());return images;}
}
